import {sha256} from '@noble/hashes/sha2.js';
const hex = bytes => Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
const CHUNK_SIZE = 768;
const MAX_IMAGE_SIZE = 2 * 1024 * 1024;

// Always release an upload started by this page after a failure, so the next attempt need not wait for expiry.
export async function uploadFirmware(rpc, file, progress = () => {}) {
	if (!file || file.size < CHUNK_SIZE || file.size > MAX_IMAGE_SIZE) throw new Error('Choose a compatible application .bin up to 2 MB.');
	const bytes = new Uint8Array(await file.arrayBuffer());
	if (bytes[0] !== 0xe9) throw new Error('This is not an ESP application image. Select firmware.bin, not a filesystem image.');
	let started = false;
	try {
		await rpc({op: 'uploadBegin', body: {size: bytes.length, sha256: hex(sha256(bytes))}});
		started = true;
		progress(0, bytes.length);
		for (let offset = 0; offset < bytes.length; offset += CHUNK_SIZE) {
			await rpc({op: 'uploadChunk', body: {offset, data: hex(bytes.subarray(offset, offset + CHUNK_SIZE))}});
			progress(Math.min(offset + CHUNK_SIZE, bytes.length), bytes.length);
		}
		await rpc({op: 'uploadFinish', body: {}});
	} catch (error) {
		if (started) { try { await rpc({op: 'uploadAbort'}); } catch {} }
		throw error;
	}
}
